import type { Difficulty, Domain } from '@/api/types';
import type { PageHead } from './seoHead';

/*
 * The document of a /learn page (/data/learn/<path>.json), generated by scripts/learn-pages.mjs from
 * content/curriculum.yaml and the public catalog. It holds only what the page shows.
 */

export interface LearnCrumb {
  label: string;
  to?: string;
}
export interface LearnLabLink {
  id: string;
  title: string;
  to: string;
  difficulty: Difficulty;
  minutes: number;
}
export interface LearnPathLink {
  id: string;
  title: string;
  to: string;
  labs: number;
  level?: string;
  time: string;
}
export interface LearnDomainLink {
  id: Domain;
  name: string;
  to: string;
}
export interface LearnExamLink {
  id: string;
  title: string;
  to: string;
  tasks?: number;
  minutes?: number;
  passMark?: number;
  domain?: LearnDomainLink;
}
interface LearnBase {
  path: string;
  head: PageHead;
  crumbs: LearnCrumb[];
  title: string;
  lead: string;
}
export interface LearnLabDoc extends LearnBase {
  kind: 'lab';
  lab: { difficulty: Difficulty; minutes: number; domain?: LearnDomainLink; skills: string[]; paths: { id: string; title: string; module: string; to: string }[]; related: LearnLabLink[] };
}
export interface LearnPathDoc extends LearnBase {
  kind: 'path';
  /** The document's `path` is its URL; the learning path itself is `learningPath`. */
  learningPath: { level?: string; labs: number; time: string; domain?: LearnDomainLink; prerequisites: LearnPathLink[]; modules: { id: string; title: string; labs: LearnLabLink[] }[]; related: LearnPathLink[]; exams: LearnExamLink[] };
}
export interface LearnExamDoc extends LearnBase {
  kind: 'exam';
  exam: { open: boolean; tasks: number; minutes: number; passMark: number; domain?: LearnDomainLink; objectives: { name: string; weight: number }[]; rules: string[]; docsAllowed?: string; paths: LearnPathLink[] };
}
export interface LearnDomainDoc extends LearnBase {
  kind: 'domain';
  domain: { labCount: number; groups: { id: string; title: string; labs: LearnLabLink[] }[]; paths: LearnPathLink[]; exams: LearnExamLink[] };
}
export interface LearnDomainCard {
  id: Domain;
  name: string;
  to: string;
  lead: string;
  labs: number;
  paths: number;
}
export interface LearnLabsIndexDoc extends LearnBase {
  kind: 'labs-index';
  labsIndex: { domains: LearnDomainCard[]; paths: LearnPathLink[]; pathCount: number; examCount: number };
}
export interface LearnPathsIndexDoc extends LearnBase {
  kind: 'paths-index';
  pathsIndex: { domains: (LearnDomainLink & { paths: LearnPathLink[] })[] };
}
export interface LearnExamsIndexDoc extends LearnBase {
  kind: 'exams-index';
  examsIndex: { exams: LearnExamLink[] };
}
export type LearnDoc = LearnLabDoc | LearnPathDoc | LearnExamDoc | LearnDomainDoc | LearnLabsIndexDoc | LearnPathsIndexDoc | LearnExamsIndexDoc;
